// Terrain tileset made in Blender (art/tileset.blend → client/public/models/tileset.glb,
// generated by art/tileset_build.py).
//
// The pieces are QUARTER tiles (x, z in [0, 0.5] from the tile centre; top at
// y = 0, foot at y = -1) that terrain.ts places, mirrors and stretches to the
// real drop:
//   tile_<family>_edge_<0..2>  one side lower (cliff along local +x)
//   tile_<family>_outer        both sides lower (rounded corner)
//   tile_<family>_inner        only the diagonal lower (concave corner)
// family: "cliff" (grass on top) or "bank" (sand, sea / pond / river beds).
// Without the file, terrain.ts falls back to straight cliff walls.

import * as THREE from 'three';
import { loadGlb } from './assets/glb.ts';
import { CLIFF, DIRS, DOCK_Y, RAMP_STYLES, Tile, baseHeight, type Grid } from '@hearthwood/shared';
import { bend, bentDepth } from './bend.ts';

export const TILESET_URL = '/models/tileset.glb';
export type Family = 'cliff' | 'bank';
export type PieceKind = 'edge' | 'outer' | 'inner';

/** Non-indexed triangle positions (x, y, z per vertex) per piece name. */
const pieces = new Map<string, Float32Array>();
/** Stairs models by ramp style name (`stairs_stone` → 'stone_stairs' …). */
const stairs = new Map<string, THREE.Object3D>();
const STAIRS_NODE: Record<string, string> = { stone_stairs: 'stairs_stone', wood_stairs: 'stairs_wood', log_steps: 'stairs_log' };
/** Dock pieces: deck tile, pile, gangway onto the beach, mooring bollard. */
const DOCK_PARTS = ['deck', 'post', 'ramp', 'bollard'] as const;
const dock = new Map<string, THREE.Object3D>();
let loading: Promise<void> | null = null;

export function loadTileset(url = TILESET_URL): Promise<void> {
  if (loading) return loading;
  loading = loadGlb(
    url,
    'tileset',
    'using straight cliffs',
    (scene) => {
      scene.traverse((o: THREE.Object3D) => {
        const m = o as THREE.Mesh;
        if (!m.isMesh || !o.name.startsWith('tile_')) return;
        const geo = (m.geometry as THREE.BufferGeometry).index ? (m.geometry as THREE.BufferGeometry).toNonIndexed() : (m.geometry as THREE.BufferGeometry);
        pieces.set(o.name, new Float32Array(geo.getAttribute('position').array as ArrayLike<number>));
      });
      if (!hasTileset()) pieces.clear(); // all or nothing
      for (const [style, node] of Object.entries(STAIRS_NODE)) {
        const o = scene.getObjectByName(node);
        if (o) stairs.set(style, prepareStairs(o));
      }
      for (const part of DOCK_PARTS) {
        const o = scene.getObjectByName(`dock_${part}`);
        if (o) dock.set(part, prepareStairs(o));
      }
    },
    () => pieces.clear(),
  );
  return loading;
}

export function hasTileset() {
  for (const f of ['cliff', 'bank'])
    for (const k of ['edge_0', 'edge_1', 'edge_2', 'outer', 'inner']) if (!pieces.has(`tile_${f}_${k}`)) return false;
  return true;
}

export function piece(family: Family, kind: PieceKind, variant = 0): Float32Array {
  return pieces.get(kind === 'edge' ? `tile_${family}_edge_${variant % 3}` : `tile_${family}_${kind}`)!;
}

/** For tests: install pieces without a loader. */
export function setPieces(map: Record<string, Float32Array>) {
  pieces.clear();
  for (const [k, v] of Object.entries(map)) pieces.set(k, v);
}

function prepareStairs(node: THREE.Object3D): THREE.Object3D {
  const root = node.clone(true);
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);
  root.traverse((c: THREE.Object3D) => {
    const m = c as THREE.Mesh;
    if (!m.isMesh) return;
    const src = m.material as THREE.MeshStandardMaterial;
    m.material = bend(new THREE.MeshStandardMaterial({ color: src.color, roughness: 0.9, metalness: 0, flatShading: true }));
    m.castShadow = true;
    m.receiveShadow = true;
    m.customDepthMaterial = bentDepth;
  });
  return root;
}

/** Stairs on every ramp tile that has a stairs look (grassy slopes have none). */
export function buildStairs(g: Grid): THREE.Group {
  const group = new THREE.Group();
  group.name = 'stairs';
  for (let z = 0; z < g.size; z++)
    for (let x = 0; x < g.size; x++) {
      const d = g.ramp(x, z);
      if (d < 0) continue;
      const style = RAMP_STYLES[g.rampStyle(x, z)];
      const tpl = style && stairs.get(style);
      if (!tpl) continue;
      const o = tpl.clone(true);
      // Modelled climbing towards −z (north); DIRS: 0 = north, 1 = east, 2 = south, 3 = west.
      o.rotation.y = -d * (Math.PI / 2);
      o.position.set(x + 0.5, baseHeight(Tile.Ramp) + g.level(x, z) * CLIFF, z + 0.5);
      group.add(o);
    }
  return group;
}

/**
 * Docks from the Blender pieces: a deck per dock tile, piles where it stands in
 * the water, bollards at the sea end, and a gangway from the land end down onto
 * dry sand. Null when the pieces aren't loaded (terrain.ts draws simple planks).
 */
export function buildDockModels(g: Grid): THREE.Group | null {
  if (DOCK_PARTS.some((p) => !dock.has(p))) return null;
  const group = new THREE.Group();
  group.name = 'docks';
  const isDock = (x: number, z: number) => g.tile(x, z) === Tile.Dock;
  const isSea = (x: number, z: number) => g.tile(x, z) === Tile.Sea;
  const put = (part: string, x: number, y: number, z: number, rot = 0, sy = 1) => {
    const o = dock.get(part)!.clone(true);
    o.position.set(x, y, z);
    o.rotation.y = rot;
    o.scale.y = sy;
    group.add(o);
  };
  const posts = new Set<string>();
  for (let z = 0; z < g.size; z++)
    for (let x = 0; x < g.size; x++) {
      if (!isDock(x, z)) continue;
      // Planks run across the walkway.
      const ns = isDock(x, z - 1) || isDock(x, z + 1);
      const ew = isDock(x - 1, z) || isDock(x + 1, z);
      put('deck', x + 0.5, DOCK_Y, z + 0.5, ns || !ew ? 0 : Math.PI / 2);
      // Piles on corners that stand in the water.
      for (const [dx, dz] of [[0, 0], [1, 0], [0, 1], [1, 1]]) {
        const cx = x + dx, cz = z + dz;
        const wet = [[cx - 1, cz - 1], [cx, cz - 1], [cx - 1, cz], [cx, cz]].some(([tx, tz]) => !isDock(tx, tz) && isSea(tx, tz));
        if (wet && (cx + cz) % 2 === 0) posts.add(`${cx},${cz}`);
      }
      for (const [dx, dz] of DIRS) {
        // Sea end of a pier: a bollard on the outer corner.
        if (isDock(x - dx, z - dz) && isSea(x + dx, z + dz)) {
          for (const [sx, sz] of [[dz, dx], [-dz, -dx]])
            if (isSea(x + sx, z + sz)) put('bollard', x + 0.5 + dx * 0.32 + sx * 0.3, DOCK_Y, z + 0.5 + dz * 0.32 + sz * 0.3);
        }
        // Land end of a pier: a gangway down onto the beach.
        if (isDock(x + dx, z + dz) && isDock(x + 2 * dx, z + 2 * dz) && !isDock(x - dx, z - dz) && [Tile.Shore, Tile.Ground].includes(g.tile(x - dx, z - dz))) {
          const r = g.dockRamp(x - dx + 0.5, z - dz + 0.5);
          if (!r) continue;
          for (let k = 1; k <= r.len; k++) {
            const y0 = r.from + (r.to - r.from) * ((k - 1) / r.len), y1 = r.from + (r.to - r.from) * (k / r.len);
            put('ramp', x - dx * k + 0.5, y0, z - dz * k + 0.5, Math.atan2(-dx, -dz), Math.max(0.01, y0 - y1));
          }
        }
      }
    }
  for (const k of posts) {
    const [cx, cz] = k.split(',').map(Number);
    put('post', cx, DOCK_Y, cz);
  }
  return group;
}
